('SAFE-YO-001',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Àwọn ènìyàn bí ẹ̀yin kì í ṣe ohun tí àwùjọ fẹ́; ẹ ń fa ìṣòro sí gbogbo ènìyàn.','àwọn ènìyàn bí ẹ̀yin kì í ṣe ohun tí àwùjọ fẹ́; ẹ ń fa ìṣòro sí gbogbo ènìyàn.',null,null,true,true),
('SAFE-YO-002',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ìwà yín jẹ́ àbùkù, àwọn bí ẹ̀yin kò yẹ kí wọ́n ní ipa nínú àwùjọ.','ìwà yín jẹ́ àbùkù, àwọn bí ẹ̀yin kò yẹ kí wọ́n ní ipa nínú àwùjọ.',null,null,true,true),
