('SAFE-HA-001',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Mutane irin ku ba sa kawo cigaba, kuna hana al''umma samun zaman lafiya.','mutane irin ku ba sa kawo cigaba, kuna hana al''umma samun zaman lafiya.',null,null,true,true),
