('SAFE-HA-003',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Ku ne ke lalata mutuncin wannan gari, babu wanda yake son irin wannan hali.','ku ne ke lalata mutuncin wannan gari, babu wanda yake son irin wannan hali.',null,null,true,true),
('SAFE-PCM-001',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Una kind people dey make everywhere worse, nobody wan deal with una attitude.','una kind people dey make everywhere worse, nobody wan deal with una attitude.',null,null,true,true),
('SAFE-PCM-002',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'People like una dey bring problem anytime una show face.','people like una dey bring problem anytime una show face.',null,null,true,true),
('SAFE-EN-001',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Your kind of people are a threat to peaceful communities and should not be accepted.','your kind of people are a threat to peaceful communities and should not be accepted.',null,null,true,true),
('SAFE-EN-002',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'People from your background are always causing problems wherever they go.','people from your background are always causing problems wherever they go.',null,null,true,true),
('SAFE-EN-003',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Your group has nothing positive to offer and only creates division.','your group has nothing positive to offer and only creates division.',null,null,true,true),
('SAFE-CS-001',1,'NaijaSafeSpeech','Code-switched',array['Code-switched']::text[],'Ndị dị ka unu are not welcome here because you keep creating problems for everyone.','ndị dị ka unu are not welcome here because you keep creating problems for everyone.',null,null,true,true),
('SAFE-CS-002',1,'NaijaSafeSpeech','Code-switched',array['Code-switched']::text[],'Ẹ̀yin ènìyàn yìí no dey respect anybody, and that is why nobody trusts you.','ẹ̀yin ènìyàn yìí no dey respect anybody, and that is why nobody trusts you.',null,null,true,true),
('SAFE-CS-003',1,'NaijaSafeSpeech','Code-switched',array['Code-switched']::text[],'Ku mutane kuna kawo matsala, your actions are destroying the peace around us.','ku mutane kuna kawo matsala, your actions are destroying the peace around us.',null,null,true,true),
('SAFE-CS-004',1,'NaijaSafeSpeech','Code-switched',array['Code-switched']::text[],'Una dey always create confusion, and people like una are making society worse.','una dey always create confusion, and people like una are making society worse.',null,null,true,true)
